import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.DUTPmUpA.js";const f=JSON.parse('{"title":"Справочник по типам файлов активов","description":"","frontmatter":{"title":"Справочник по типам файлов активов","author":"Noya","steamId":"76561198046984233","date":"28.05.2015"},"headers":[],"relativePath":"assets/asset-file-type-reference.md","filePath":"assets/asset-file-type-reference.md"}'),c={name:"assets/asset-file-type-reference.md"};function a(s,t,n,p,i,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<p>чник по типам файлов активов</p><p>Этот список содержит всю информацию о типах активов, а также связанные с ними инструменты и руководства, объясняющие форматы.</p><table tabindex="0"><thead><tr><th>Тип</th><th>.Расширение</th><th>Эквивалент S1</th><th>Информация, формат, декомпилятор</th></tr></thead><tbody><tr><td>Анимация</td><td><code>vanim</code></td><td><code>smd</code></td><td>Файлы <code>.smd</code> добавляются в <code>.vmdl</code> через редактор моделей для создания файлов <code>.vanim</code>.</td></tr><tr><td>Анимационная последовательность</td><td><code>vgarp</code></td><td>?</td><td>??</td></tr><tr><td>Карта</td><td><code>vmap</code></td><td><code>vmf</code></td><td>Hammer Files.<br>Декомпилятор пока не известен людям, но ходят слухи, что над ним работает волшебный пингвин.</td></tr><tr><td>Материал</td><td><code>vmat</code></td><td><code>vmt</code></td><td>Сделано с использованием файлов <code>.tga</code> в редакторе материалов. <br> Декомпилятор: <a href="https://s2v.app/" target="_blank" rel="noreferrer">S2V</a></td></tr><tr><td>Модель</td><td><code>vmdl</code></td><td><code>mdl</code></td><td>Руководство по декомпиляции: <a href="./models/mdl-to-vmdl-conversion">MDL to VMDL Conversion</a></td></tr><tr><td>сетка</td><td><code>vmesh</code></td><td><code>smd</code>,<code>dmx</code>,<code>fbx</code></td><td>Определяет форму модели. <br> Загружается в редактор моделей для создания новой модели.</td></tr><tr><td>Частица</td><td><code>vpcf</code></td><td><code>pcf</code></td><td>Декомпилятор: <a href="https://s2v.app/" target="_blank" rel="noreferrer">S2V</a><br> Пока не известен метод преобразования PCF в VPCF.</td></tr><tr><td>Звук</td><td><code>vsnd</code></td><td><code>wav</code></td><td>Берет файлы <code>wav</code>/<code>mp3</code> и преобразует их в этот файл с помощью <code>.vsndevts</code></td></tr><tr><td>Звуковое событие</td><td><code>vsndevts</code></td><td><code>txt</code></td><td><a href="https://github.com/pingzing/dota2-sound-editor" target="_blank" rel="noreferrer">Sound Editor</a> считывает строки Source 1, которые идентичны строкам, используемым в Source 2. <br>Guide: <a href="./custom-sounds">Adding and playing Custom Sounds</a></td></tr><tr><td>Текстура</td><td><code>vtex</code></td><td><code>vtx</code></td><td>Скомпилировано из файлов <code>.tga</code>. <br>Руководство: <a href="/assets/extracting-and-compiling-vtex-files">Extracting and Compiling VTEX files</a></td></tr></tbody></table><p>Большинство форматов Source 2 можно декомпилировать с помощью <a href="https://s2v.app/" target="_blank" rel="noreferrer">Source 2 Viewer</a>.</p><p>Он будет обновляться по мере того, как мы будем получать больше знаний и создавать больше инструментов для декомпиляции и преобразования файлов.</p>',5)])])}const v=d(c,[["render",a]]);export{f as __pageData,v as default};
